// A struct handler and a func handler are interchangeable.
type greeter struct{ name string }

func (g greeter) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "hello from %s", g.name)
}

func main() {
	// http.HandlerFunc adapts a plain func into a Handler.
	var h1 http.Handler = http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "ok")
	})
	var h2 http.Handler = greeter{name: "svc"}
	_ = http.ListenAndServe(":8080", h2) // any Handler works
	_ = h1
}
// GET / (via h1) -> "ok"; via h2 -> "hello from svc"

func main() {
	mux := http.NewServeMux()
	// Go 1.22+ method + wildcard patterns.
	mux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id") // extract the {id} segment
		fmt.Fprintf(w, "user %s", id)
	})
	mux.HandleFunc("POST /users", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusCreated)
	})
	_ = http.ListenAndServe(":8080", mux) // the mux is the server's Handler
}
// GET /users/42 -> "user 42"; POST /users -> 201 Created

// Middleware: takes the next Handler, returns a wrapping Handler.
func logging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r) // call the wrapped handler
		log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start))
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "hello")
	})
	_ = http.ListenAndServe(":8080", logging(mux)) // wrap the whole mux
}
// log: "GET / 128\u00b5s" then body "hello"

func createUser(w http.ResponseWriter, r *http.Request) {
	if r.Header.Get("Content-Type") != "application/json" {
		http.Error(w, "want JSON", http.StatusUnsupportedMediaType)
		return
	}
	w.Header().Set("Content-Type", "application/json") // 1. headers first
	w.Header().Set("Location", "/users/42")
	w.WriteHeader(http.StatusCreated)                   // 2. status next (201)
	json.NewEncoder(w).Encode(map[string]int{"id": 42}) // 3. body last
	// Writing the body BEFORE WriteHeader would lock the status at 200.
}
// -> 201 Created, Content-Type: application/json, {"id":42}

// One shared client, reused across all calls; pools connections.
var client = &http.Client{Timeout: 10 * time.Second} // never zero in prod

func fetch(url string) ([]byte, error) {
	resp, err := client.Get(url)
	if err != nil {
		return nil, err
	}
	defer func() {
		io.Copy(io.Discard, resp.Body) // drain any unread bytes
		resp.Body.Close()              // return conn to the pool
	}()
	return io.ReadAll(resp.Body)
}
// Reusing `client` reuses keep-alive connections; a fresh client per call
// defeats pooling and can exhaust sockets.

// Server: bound slow clients with timeouts.
srv := &http.Server{
	Addr:         ":8080",
	ReadTimeout:  5 * time.Second,
	WriteTimeout: 10 * time.Second,
	IdleTimeout:  60 * time.Second,
}
go srv.ListenAndServe()

// Client: propagate a deadline via context to downstream calls.
ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
defer cancel()
req, _ := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
resp, err := client.Do(req) // cancelled when ctx times out
_ = err
_ = resp
// Context cancellation propagates to DBs/RPCs invoked inside the handler.

