package main

import (
	"encoding/json"
	"net/http"
	"time"
)

func getUser(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")                         // from "/users/{id}"
	w.Header().Set("Content-Type", "application/json") // set headers FIRST
	w.WriteHeader(http.StatusOK)                    // then status
	json.NewEncoder(w).Encode(map[string]string{"id": id})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /users/{id}", getUser) // method+wildcard pattern

	srv := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  5 * time.Second,  // slow clients can't stall reads
		WriteTimeout: 10 * time.Second, // bound response time
		IdleTimeout:  60 * time.Second, // reap idle keep-alive conns
	}
	_ = srv.ListenAndServe()
}

// GET /users/42  ->  {"id":"42"}

