package solution

import "net/http"

// statusRecorder wraps a ResponseWriter to capture the status code.
type statusRecorder struct {
	http.ResponseWriter
	status      *int
	wroteHeader bool
}

// WriteHeader records the status, then delegates.
func (s *statusRecorder) WriteHeader(code int) {
	if !s.wroteHeader {
		*s.status = code
		s.wroteHeader = true
	}
	s.ResponseWriter.WriteHeader(code)
}

// Write triggers an implicit 200 if WriteHeader wasn't called, mirroring net/http.
func (s *statusRecorder) Write(b []byte) (int, error) {
	if !s.wroteHeader {
		*s.status = http.StatusOK
		s.wroteHeader = true
	}
	return s.ResponseWriter.Write(b)
}

// WrapStatus returns a handler recording the response status into *int.
func WrapStatus(next http.Handler) (http.Handler, *int) {
	status := new(int)
	*status = http.StatusOK // default if nothing is ever written
	h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rec := &statusRecorder{ResponseWriter: w, status: status}
		next.ServeHTTP(rec, r)
	})
	return h, status
}

