package solution

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestWrapStatus(t *testing.T) {
	cases := []struct {
		name    string
		handler http.HandlerFunc
		want    int
	}{
		{"explicit 404", func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(404) }, 404},
		{"implicit 200", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("ok")) }, 200},
		{"created 201", func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(201); w.Write([]byte("x")) }, 201},
	}
	for _, c := range cases {
		wrapped, status := WrapStatus(c.handler)
		req := httptest.NewRequest("GET", "/", nil)
		wrapped.ServeHTTP(httptest.NewRecorder(), req)
		if *status != c.want {
			t.Errorf("%s: status=%d want %d", c.name, *status, c.want)
		}
	}
}

