// Shared, reused across all calls; pools connections via its Transport.
var client = &http.Client{Timeout: 10 * time.Second}

func fetch(ctx context.Context, url string) ([]byte, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	defer func() {
		io.Copy(io.Discard, resp.Body) // drain so the conn can be reused
		resp.Body.Close()              // return the conn to the pool
	}()
	return io.ReadAll(resp.Body)
}

package solution

import "net/http"

type Middleware = func(http.Handler) http.Handler

// Chain composes middleware left-to-right: Chain(a,b,c)(h) runs a, then b,
// then c, then h.
func Chain(mw ...Middleware) Middleware {
	return func(final http.Handler) http.Handler {
		// Wrap from the innermost (last) outward so the first listed
		// middleware ends up outermost and runs first.
		h := final
		for i := len(mw) - 1; i >= 0; i-- {
			h = mw[i](h)
		}
		return h
	}
}

package solution

import (
	"log"
	"net/http"
)

// Recover wraps next so a panic in the handler is caught, logged, and turned
// into a 500 response instead of crashing the request goroutine.
func Recover(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if rec := recover(); rec != nil {
				// Log with method/path so the panic is traceable.
				log.Printf("panic recovered: %s %s: %v", r.Method, r.URL.Path, rec)
				// Best-effort 500; if the handler already wrote headers this
				// is a no-op (status is locked), but the crash is still avoided.
				http.Error(w, "internal server error", http.StatusInternalServerError)
			}
		}()
		next.ServeHTTP(w, r) // if this panics, the deferred recover runs
	})
}
